@router.get('/api/reports/financial/download-url')
def get_financial_report_url(
    report_id: int = Query(...),
    current_user: User = Depends(get_current_user)
):
    report = FinancialReport.get_or_none(
        (FinancialReport.id == report_id) & (FinancialReport.company_id == current_user.company_id)
    )
    if not report:
        raise HTTPException(status_code=404, detail="Report not found")

    bucket = gcs_client.bucket(settings.GCS_BUCKET_NAME)
    blob = bucket.blob(report.storage_blob_name)
    signed_url = blob.generate_signed_url(
        version="v4",
        expiration=timedelta(minutes=15),
        method="GET"
    )
    return {"report_name": report.title, "url": signed_url}
